1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  input[type="date"] {
54	    padding: 0.5rem;
55	    font: inherit;
56	    border: 1px solid #d6d3d1;
57	    border-radius: 6px;
58	    background: #fff;
59	  }
60	  li .due { flex: none; font-size: 0.85rem; color: #57534e; }
61	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
62	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
63	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
64	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
65	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
66	</style>
67	</head>
68	<body>
69	<main>
70	  <h1>Todos</h1>
71	  <form id="todo-form">
72	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
73	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
74	    <button type="submit" data-testid="todo-add">Add</button>
75	  </form>
76	  <div class="filters" role="group" aria-label="Filter todos">
77	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
78	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
79	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
80	  </div>
81	  <ul data-testid="todo-list"></ul>
82	</main>
83	<script>
84	(function () {
85	  var STORAGE_KEY = 'todos';
86	  var form = document.getElementById('todo-form');
87	  var input = document.querySelector('[data-testid="todo-input"]');
88	  var list = document.querySelector('[data-testid="todo-list"]');
89	  var dueInput = document.querySelector('[data-testid="todo-due"]');
90	
91	  // [REQ-001]
92	  function makeId() {
93	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
94	      return window.crypto.randomUUID();
95	    }
96	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
97	  }
98	
99	  // [REQ-001]
100	  function loadTodos() {
101	    try {
102	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
103	      return Array.isArray(parsed) ? parsed : [];
104	    } catch (e) {
105	      return [];
106	    }
107	  }
108	
109	  // [REQ-001]
110	  function saveTodos() {
111	    try {
112	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
113	    } catch (e) {}
114	  }
115	
116	  var todos = loadTodos();
117	  var filter = 'all';
118	  var filterButtons = document.querySelectorAll('[data-filter]');
119	
120	  // [REQ-002] Active todos first, then completed; each group keeps insertion order.
121	  function orderedTodos() {
122	    var active = todos.filter(function (t) { return !t.completed; });
123	    var done = todos.filter(function (t) { return !!t.completed; });
124	    return active.concat(done);
125	  }
126	
127	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
128	  function todayLocal() {
129	    var d = new Date();
130	    var m = d.getMonth() + 1;
131	    var day = d.getDate();
132	    return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
133	  }
134	
135	  // [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
136	  function normalizeDue(value) {
137	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
138	  }
139	
140	  // [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
141	  function isOverdue(todo, today) {
142	    var due = normalizeDue(todo.due);
143	    return due !== '' && due < today;
144	  }
145	
146	  // [REQ-002]
147	  function isVisible(todo) {
148	    if (filter === 'active') return !todo.completed;
149	    if (filter === 'completed') return !!todo.completed;
150	    return true;
151	  }
152	
153	  // [REQ-001]
154	  function render() {
155	    list.textContent = '';
156	    filterButtons.forEach(function (btn) {
157	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
158	    });
159	    var today = todayLocal();
160	    orderedTodos().filter(isVisible).forEach(function (todo) {
161	      var li = document.createElement('li');
162	      li.setAttribute('data-testid', 'todo-item');
163	      li.setAttribute('data-id', todo.id);
164	      li.setAttribute('data-completed', String(!!todo.completed));
165	      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
166	
167	      var toggle = document.createElement('input');
168	      toggle.type = 'checkbox';
169	      toggle.setAttribute('data-testid', 'todo-toggle');
170	      toggle.setAttribute('aria-label', 'Mark complete');
171	      toggle.checked = !!todo.completed;
172	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
173	      li.appendChild(toggle);
174	
175	      var text = document.createElement('span');
176	      text.setAttribute('data-testid', 'todo-text');
177	      text.textContent = todo.text;
178	
179	      var del = document.createElement('button');
180	      del.type = 'button';
181	      del.setAttribute('data-testid', 'todo-delete');
182	      del.setAttribute('aria-label', 'Delete todo');
183	      del.textContent = 'Delete';
184	      del.addEventListener('click', function () { deleteTodo(todo.id); });
185	
186	      li.appendChild(text);
187	
188	      // [REQ-003] Show the stored string as-is so no timezone shift can occur.
189	      var due = normalizeDue(todo.due);
190	      if (due) {
191	        var dueEl = document.createElement('span');
192	        dueEl.className = 'due';
193	        dueEl.setAttribute('data-testid', 'todo-due-date');
194	        dueEl.textContent = 'Due ' + due;
195	        li.appendChild(dueEl);
196	      }
197	
198	      li.appendChild(del);
199	      list.appendChild(li);
200	    });
201	  }
202	
203	  // [REQ-001]
204	  function addTodo(text, due) {
205	    text = text.trim();
206	    if (!text) return;
207	    // [REQ-003] due is optional, stored as a YYYY-MM-DD string or ''.
208	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due) });
209	    saveTodos();
210	    render();
211	  }
212	
213	  // [REQ-002]
214	  function toggleTodo(id) {
215	    todos.forEach(function (t) {
216	      if (t.id === id) t.completed = !t.completed;
217	    });
218	    saveTodos();
219	    render();
220	  }
221	
222	  // [REQ-002]
223	  function setFilter(value) {
224	    filter = value;
225	    render();
226	  }
227	
228	  filterButtons.forEach(function (btn) {
229	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
230	  });
231	
232	  // [REQ-001]
233	  function deleteTodo(id) {
234	    todos = todos.filter(function (t) { return t.id !== id; });
235	    saveTodos();
236	    render();
237	  }
238	
239	  form.addEventListener('submit', function (e) {
240	    e.preventDefault();
241	    addTodo(input.value, dueInput.value);
242	    input.value = '';
243	    dueInput.value = '';
244	    input.focus();
245	  });
246	
247	  // [REQ-003] Refresh overdue state when the page returns after the date may have changed.
248	  document.addEventListener('visibilitychange', function () {
249	    if (!document.hidden) render();
250	  });
251	
252	  render();
253	})();
254	</script>
255	</body>
256	</html>
