    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  input[type="date"] {''','''  input[type="date"], select {''')
rep('''  .filters { display: flex;''','''  /* [REQ-004] Priority colour: left stripe, set after overdue so it keeps its own colour. */
