  li[data-priority="med"] { border-left-color: #f59e0b; }
  li[data-priority="low"] { border-left-color: #a8a29e; }
  .filters { display: flex;''')
rep('''    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
''','''    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
    <select data-testid="todo-priority" aria-label="Priority">
      <option value="low">Low</option>
      <option value="med" selected>Med</option>
      <option value="high">High</option>
    </select>
''')
rep('''  var dueInput = document.querySelector('[data-testid="todo-due"]');
''','''  var dueInput = document.querySelector('[data-testid="todo-due"]');
  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
''')
rep('''  // [REQ-002]
  function isVisible''','''  // [REQ-004] Only low, med or high; anything else (including older todos) is med.
  function normalizePriority(value) {
    return value === 'low' || value === 'high' ? value : 'med';
  }

  // [REQ-002]
  function isVisible''')
rep('''      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
''','''      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
      li.setAttribute('data-priority', normalizePriority(todo.priority)); // [REQ-004]
''')
rep('''  function addTodo(text, due) {''','''  function addTodo(text, due, priority) {''')
rep('''completed: false, due: normalizeDue(due) });''','''completed: false, due: normalizeDue(due), priority: normalizePriority(priority) }); // [REQ-004]''')
rep('''    addTodo(input.value, dueInput.value);
    input.value = '';
    dueInput.value = '';
''','''    addTodo(input.value, dueInput.value, priorityInput.value);
    input.value = '';
    dueInput.value = '';
    priorityInput.value = 'med';
''')
open(p,'w').write(s)
